/* prog19_palindrome_checker.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program reads a single command‑line argument, normalises it
 * (keeps only alphanumeric characters and lower‑cases letters),
 * checks whether the normalised string is a palindrome and prints
 * the result.  If the argument is longer than 1024 characters the
 * program prints "TOO_LONG".  With no argument the empty string is
 * considered a palindrome.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv)
{
    /* No argument – treat empty string as a palindrome */
    if (argc <= 1) {
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* Length limit enforced by the original binary (0x400 = 1024) */
    if (len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    /* Normalise the input: keep only alphanumerics, lower‑case letters */
    char norm[1025];               /* enough for the whole input + NUL */
    size_t n = 0;

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (isupper(c))
                c = (unsigned char)tolower(c);
            norm[n++] = (char)c;
        }
    }
    norm[n] = '\0';

    /* Palindrome test on the normalised string */
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
